using System.Text.Json;
using System.Text.Json.Nodes;
namespace RisingLands;
public static class TimingTests {
    static void Check(bool ok,string message){if(!ok)throw new Exception("FAIL: "+message);Console.WriteLine("PASS: "+message);}
    public static void Run(string root){
        using var schedule=JsonDocument.Parse(File.ReadAllText(PackageLayout.FromBase("Content/Data/projectile_schedule.json")));int checkedUpdates=0;
        foreach(var item in schedule.RootElement.GetProperty("cases").EnumerateArray()){
            var arrow=new Arrow{StepPixels=30,StartX=item.GetProperty("start_x").GetInt32(),EndX=item.GetProperty("end_x").GetInt32(),StartY=item.GetProperty("y").GetInt32(),EndY=item.GetProperty("y").GetInt32()};
            foreach(var frame in item.GetProperty("frames").EnumerateArray()){arrow.Progress=frame.GetProperty("tick").GetInt32()*30;var actual=arrow.ActiveParts().ToArray();var expected=frame.GetProperty("active").EnumerateArray().ToArray();if(actual.Length!=expected.Length||arrow.HasImpacted!=(frame.GetProperty("impact_count").GetInt32()==1))throw new Exception("Native schedule mismatch");for(int i=0;i<actual.Length;i++)if(actual[i]!=(expected[i].GetProperty("type").GetInt32(),expected[i].GetProperty("x").GetInt32(),expected[i].GetProperty("y").GetInt32(),expected[i].GetProperty("remaining").GetInt32()))throw new Exception("Native trail mismatch");checkedUpdates++;}
        }
        Check(checkedUpdates==71,"71 complete x86 projectile updates match head, four trail parts and impact boundary");
        var visuals=new VisualCatalog();Simulation Create(bool ranged){var w=LegacyAssets.Map(PackageLayout.Asset(root,"CD/WORLD/MONDE01.ETA"));visuals.Apply(w);return new Simulation(Simulation.TrainingWorld(w,ranged));}Actor Hero(Simulation s,int type)=>s.World.Units.First(u=>u.Type==type&&u.Owner==0);
        foreach(int type in new[]{0,8}){var sim=Create(type==8);var hero=Hero(sim,type);var enemy=sim.World.Units.Last();if(type==0){enemy.X=hero.X+1024;enemy.Y=hero.Y;}sim.Attack(hero,enemy);for(int tick=1;tick<=11;tick++){sim.Step();CheckTick(sim,hero,enemy,tick);}
            Check(enemy.Health==100&&sim.Arrows.Count==0,"type "+type+" waits through eleven updates before release");string pending=sim.Serialize();var copy=Create(type==8);copy.Restore(pending);sim.Step();copy.Step();Check(hero.AttackWindup==0&&(type==8?sim.Arrows.Count==1:enemy.Health==81),"type "+type+" releases exactly on original twelfth update");for(int i=0;i<150;i++){sim.Step();copy.Step();}Check(sim.Serialize()==copy.Serialize(),"type "+type+" resumes pending attack deterministically");}
        var canceled=Create(true);var a=Hero(canceled,8);var b=canceled.World.Units.Last();canceled.Attack(a,b);for(int i=0;i<6;i++)canceled.Step();canceled.Stop(a);for(int i=0;i<30;i++)canceled.Step();Check(a.AttackWindup==0&&b.Health==100&&canceled.Arrows.Count==0,"stop during preparation cancels the unreleased arrow");
        var tail=Create(true);a=Hero(tail,8);b=tail.World.Units.Last();a.X=(b.X/32-149)*32;a.Y=b.Y;tail.Attack(a,b);for(int i=0;i<12;i++)tail.Step();tail.Stop(a);Check(tail.Arrows.Single().Length==149,"impact-save fixture straddles native head and trail completion");for(int i=0;i<5;i++)tail.Step();Check(b.Health==84&&tail.Arrows.Single().HasImpacted&&!tail.Arrows.Single().Finished,"head damages once while original trail remains visible");var tailCopy=Create(true);tailCopy.Restore(tail.Serialize());tail.Step();tailCopy.Step();Check(b.Health==84&&tail.Arrows.Count==0&&tail.Serialize()==tailCopy.Serialize(),"saving residual trail never repeats damage after restore");
        var modern=Create(true);a=Hero(modern,8);b=modern.World.Units.Last();modern.Attack(a,b);for(int i=0;i<12;i++)modern.Step();var v6=JsonNode.Parse(modern.Serialize())!;v6["Version"]=6;v6["Arrows"]![0]!.AsObject().Remove("StepPixels");foreach(var u in v6["Units"]!.AsArray())u!.AsObject().Remove("AttackWindup");var legacy=Create(true);legacy.Restore(v6.ToJsonString());legacy.Step();Check(legacy.Arrows.Single().StepPixels==8&&legacy.Arrows.Single().Progress==8,"v6 in-flight saves keep their old eight-pixel schedule");var legacyCopy=Create(true);legacyCopy.Restore(legacy.Serialize());Check(legacyCopy.Serialize()==legacy.Serialize(),"migrated legacy flight saves again without losing its schedule");
        var invalid=JsonNode.Parse(modern.Serialize())!;invalid["Units"]!.AsArray().First(u=>u!["Slot"]!.GetValue<int>()==a.Slot)!["AttackWindup"]=12;string unchanged=modern.Serialize();try{modern.Restore(invalid.ToJsonString());throw new Exception("Bad preparation accepted");}catch(InvalidDataException){}Check(modern.Serialize()==unchanged,"invalid preparation state rejected atomically");
        void CheckTick(Simulation sim,Actor hero,Actor enemy,int tick){if(hero.AttackWindup!=12-tick||enemy.Health!=100||sim.Arrows.Count!=0)throw new Exception("Premature release");var visual=hero.Type==0?visuals.AttackVisual:visuals.ArcherVisual;var expected=visual.Frames.First(f=>f.Direction==hero.Direction&&f.Phase==tick/2);if(!visuals.Frame(hero).SequenceEqual(expected.Commands))throw new Exception("Release pose differs from native animation");}
    }
}
